def circle_circumference(r):
  return 2 * math.pi * r

def find_solution(a, b, n):
	i = 0
	while i * a <= n:
		if (n - (i * a)) % b == 0: 
			return (i, (n - (i * a)) // b)
		i = i + 1
	return None

def sum_series(n):
  if n <= 0:
    return 0
  return sum(n - 2 * i for i in range(n // 2 + 1))

